$$
\begin{aligned}
&\text { (d) Let } I=\int 2^{2^{x}} \cdot 2^{x} d x\\
&\begin{array}{l}
\text { Put } \quad t=2^{x} \\
\Rightarrow \quad d t=2^{x} \log 2 d x \\
\therefore \quad I=\int \frac{2^{t}}{\log 2} d t \\
=\frac{2^{t}}{(\log 2)^{2}}+C=\frac{2^{2^{x}}}{(\log 2)^{2}}+C \\
\therefore \quad A=\frac{1}{(\log 2)^{2}}
\end{array}
\end{aligned}
$$
